<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class DashboardController extends Controller {
 public function show(Request $r,string $type){$c=$r->user()->company_id;$b=$r->user()->branch_id;$from=now()->startOfMonth();$today=today();$sales=DB::table('sales')->where(['company_id'=>$c,'branch_id'=>$b])->where('status','paid');$purchases=DB::table('purchases')->where(['company_id'=>$c,'branch_id'=>$b])->where('status','confirmed');$expenses=DB::table('expenses')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'active','financial_status'=>'paid']);$metrics=match($type){
  'general'=>[['label'=>'Ventas hoy','value'=>(float)(clone$sales)->whereDate('created_at',$today)->sum('total'),'format'=>'money'],['label'=>'Operaciones hoy','value'=>(clone$sales)->whereDate('created_at',$today)->count(),'format'=>'number'],['label'=>'Stock crítico','value'=>$this->critical($c),'format'=>'number'],['label'=>'Pedidos web pendientes','value'=>DB::table('web_orders')->where(['company_id'=>$c,'status'=>'pending'])->count(),'format'=>'number']],
  'administrative'=>[['label'=>'Usuarios activos','value'=>DB::table('users')->where(['company_id'=>$c,'status'=>'active'])->count(),'format'=>'number'],['label'=>'Sucursales','value'=>DB::table('branches')->where(['company_id'=>$c,'status'=>'active'])->count(),'format'=>'number'],['label'=>'Eventos auditados','value'=>DB::table('audit_events')->where('company_id',$c)->where('created_at','>=',$from)->count(),'format'=>'number'],['label'=>'Notificaciones pendientes','value'=>DB::table('notifications')->where('company_id',$c)->whereNull('read_at')->count(),'format'=>'number']],
  'sales'=>[['label'=>'Ventas del mes','value'=>(float)(clone$sales)->where('created_at','>=',$from)->sum('total'),'format'=>'money'],['label'=>'Tickets','value'=>(clone$sales)->where('created_at','>=',$from)->count(),'format'=>'number'],['label'=>'Ticket promedio','value'=>(float)((clone$sales)->where('created_at','>=',$from)->avg('total')??0),'format'=>'money'],['label'=>'Devoluciones','value'=>(float)DB::table('sale_returns')->where('company_id',$c)->where('created_at','>=',$from)->sum('total'),'format'=>'money']],
  'inventory'=>[['label'=>'Valor de inventario','value'=>(float)(DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->selectRaw('SUM(s.quantity*p.average_cost) total')->value('total')??0),'format'=>'money'],['label'=>'Productos','value'=>DB::table('products')->where(['company_id'=>$c,'status'=>'active'])->count(),'format'=>'number'],['label'=>'Stock crítico','value'=>$this->critical($c),'format'=>'number'],['label'=>'Lotes por vencer','value'=>DB::table('lots')->where('company_id',$c)->whereBetween('expires_at',[$today,now()->addDays(30)])->count(),'format'=>'number']],
  'purchases'=>[['label'=>'Compras del mes','value'=>(float)(clone$purchases)->where('created_at','>=',$from)->sum('total'),'format'=>'money'],['label'=>'Documentos','value'=>(clone$purchases)->where('created_at','>=',$from)->count(),'format'=>'number'],['label'=>'Devoluciones','value'=>(float)DB::table('purchase_returns')->where('company_id',$c)->where('created_at','>=',$from)->sum('total'),'format'=>'money'],['label'=>'Saldo por pagar','value'=>(float)$this->purchaseBalance($c),'format'=>'money']],
  'cash'=>[['label'=>'Caja abierta','value'=>DB::table('cash_sessions')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'open'])->count(),'format'=>'number'],['label'=>'Ingresos hoy','value'=>(float)$this->cashSum($c,'income'),'format'=>'money'],['label'=>'Retiros hoy','value'=>(float)$this->cashSum($c,'withdrawal'),'format'=>'money'],['label'=>'Diferencias del mes','value'=>(float)DB::table('cash_sessions')->where('company_id',$c)->where('opened_at','>=',$from)->sum('difference'),'format'=>'money']],
  'financial'=>[['label'=>'Ingresos del mes','value'=>(float)(clone$sales)->where('created_at','>=',$from)->sum('total'),'format'=>'money'],['label'=>'Costo vendido','value'=>(float)$this->cost($c,$from),'format'=>'money'],['label'=>'Gastos del mes','value'=>(float)(clone$expenses)->where('expense_date','>=',$from)->sum('amount'),'format'=>'money'],['label'=>'Utilidad estimada','value'=>(float)$this->profit($c,$from),'format'=>'money']],
  'ai'=>[['label'=>'Consultas IA','value'=>DB::table('ai_logs')->where('company_id',$c)->count(),'format'=>'number'],['label'=>'Tokens consumidos','value'=>(int)DB::table('ai_logs')->where('company_id',$c)->sum('tokens'),'format'=>'number'],['label'=>'Errores IA','value'=>DB::table('ai_logs')->where(['company_id'=>$c,'status'=>'failed'])->count(),'format'=>'number'],['label'=>'Costo API','value'=>(float)DB::table('ai_logs')->where('company_id',$c)->sum('cost'),'format'=>'money']],
  'portal'=>[['label'=>'Pedidos pendientes','value'=>DB::table('web_orders')->where(['company_id'=>$c,'status'=>'pending'])->count(),'format'=>'number'],['label'=>'Pedidos del mes','value'=>DB::table('web_orders')->where('company_id',$c)->where('created_at','>=',$from)->count(),'format'=>'number'],['label'=>'Ventas potenciales','value'=>(float)DB::table('web_orders')->where('company_id',$c)->whereNot('status','cancelled')->where('created_at','>=',$from)->sum('total'),'format'=>'money'],['label'=>'Clientes web','value'=>DB::table('web_customers')->where(['company_id'=>$c,'status'=>'active'])->count(),'format'=>'number']],
  default=>abort(404,'Dashboard no disponible')};
  $trend=collect(range(6,0))->map(function($days)use($sales){$date=now()->subDays($days);return['label'=>$date->format('d/m'),'value'=>(float)(clone$sales)->whereDate('created_at',$date)->sum('total')];});
  $activity=DB::table('audit_events as a')->leftJoin('users as u','u.id','=','a.user_id')->where('a.company_id',$c)->select('a.event','a.entity','a.created_at','u.name as user_name')->latest('a.created_at')->limit(8)->get();
  return response()->json(['success'=>true,'data'=>compact('type','metrics','trend','activity')]);
 }
 private function critical(int$c):int{return DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->whereColumn('s.quantity','<=','p.minimum_stock')->count();}
 private function purchaseBalance(int$c):float{$total=(float)DB::table('purchases')->where('company_id',$c)->sum('total');$paid=(float)DB::table('purchase_payments as pp')->join('purchases as p','p.id','=','pp.purchase_id')->where('p.company_id',$c)->sum('pp.amount');return$total-$paid;}
 private function cashSum(int$c,string$type):float{return(float)DB::table('cash_movements as m')->join('cash_sessions as s','s.id','=','m.cash_session_id')->where('s.company_id',$c)->where('m.type',$type)->whereDate('m.created_at',today())->sum('m.amount');}
 private function cost(int$c,$from):float{return(float)(DB::table('sale_details as d')->join('sales as s','s.id','=','d.sale_id')->where(['s.company_id'=>$c,'s.status'=>'paid'])->where('s.created_at','>=',$from)->selectRaw('SUM(d.quantity*d.historical_unit_cost) total')->value('total')??0);}
 private function profit(int$c,$from):float{$revenue=(float)DB::table('sale_details as d')->join('sales as s','s.id','=','d.sale_id')->where(['s.company_id'=>$c,'s.status'=>'paid'])->where('s.created_at','>=',$from)->sum('d.total');$cost=$this->cost($c,$from);$expenses=(float)DB::table('expenses')->where(['company_id'=>$c,'financial_status'=>'paid'])->where('expense_date','>=',$from)->sum('amount');return$revenue-$cost-$expenses;}
}
